#!/usr/bin/python
"""Upgrade the catalog database from schema version 1 to version 2."""

import os
import sqlite3
import sys


BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DATABASE = os.path.join(BASE, "catalog.db")


def schema_version(db):
    rows = db.execute("SELECT version FROM schema_version").fetchall()
    if len(rows) != 1:
        raise RuntimeError("schema_version must contain exactly one row")
    return rows[0][0]


def product_columns(db):
    return {row[1]: row for row in db.execute("PRAGMA table_info(products)")}


def validate_v1(db):
    columns = product_columns(db)
    if set(columns) != {"id", "description"}:
        raise RuntimeError("version 1 products table has an unexpected layout")
    if columns["id"][5] != 1 or columns["description"][3] != 1:
        raise RuntimeError("version 1 products table has invalid constraints")


def validate_v2(db):
    columns = product_columns(db)
    if set(columns) != {"id", "description", "price_cents"}:
        raise RuntimeError("version 2 products table has an unexpected layout")
    price = columns["price_cents"]
    if price[2].upper() != "INTEGER" or price[3] != 1 or price[4] not in ("0", "(0)"):
        raise RuntimeError("version 2 price_cents definition is invalid")
    table_sql = db.execute(
        "SELECT sql FROM sqlite_master WHERE type='table' AND name='products'"
    ).fetchone()
    normalized = "".join((table_sql[0] if table_sql else "").lower().split())
    if "check(price_cents>=0)" not in normalized:
        raise RuntimeError("version 2 price_cents constraint is missing")


def upgrade():
    db = sqlite3.connect(DATABASE, timeout=30)
    try:
        db.execute("PRAGMA foreign_keys = ON")
        db.execute("BEGIN IMMEDIATE")
        version = schema_version(db)

        if version == 2:
            validate_v2(db)
            db.commit()
            return
        if version != 1:
            raise RuntimeError("unsupported schema version: {0}".format(version))

        validate_v1(db)
        db.execute(
            "ALTER TABLE products ADD COLUMN price_cents INTEGER NOT NULL "
            "DEFAULT 0 CHECK (price_cents >= 0)"
        )
        updated = db.execute(
            "UPDATE schema_version SET version = 2 WHERE version = 1"
        )
        if updated.rowcount != 1:
            raise RuntimeError("schema version changed during upgrade")
        db.commit()
    except Exception:
        if db.in_transaction:
            db.rollback()
        raise
    finally:
        db.close()


if __name__ == "__main__":
    try:
        upgrade()
    except Exception as error:
        print("upgrade failed: {0}".format(error), file=sys.stderr)
        sys.exit(1)
